#!/usr/bin/env bash
# Phase Q — per-script battery, run AFTER a script's training ends.
#
#  1. export fp32 with the campaign parity gates, then the fp16w ship bytes;
#  2. full-holdout read at the ADOPTED preset (CKDT, lambda 2.0 — no sweep),
#     fp32 and fp16w, with a per-row dump;
#  3. falsification control: permuted key centres, seed 4242;
#  4. the two zero-shot controls, ch192 EN (shipped) and ch80 EN (capacity
#     matched), on the same rows — the ONLY cross-generation comparator
#     (margins, never levels: a v3 holdout is generated by v3).
#
# SEED (env, default 1234) selects the Q-A replicate (PHASE_Q.md §8).  For a
# replicate seed the run is `phaseQ-<code>-v3-s<SEED>`, every output JSON gains
# a `_s<SEED>` tag, and steps 3-4 plus the fp16w half of steps 1-2 are SKIPPED
# BY DESIGN, not by omission: the EN controls are other models decoded on the
# same rows, the permutation is a property of the layout, and only the shipped
# bytes need quantizing (§8.2).  s1234 therefore stays the complete battery.
#
# `ru` is a case here too: its holdout read is the GQ-T trivial-fit diagnostic,
# and it additionally gets the REAL Yandex probe with a per-row dump — the only
# accuracy claim any of these six models has.
set -u
CTC=/home/will/git/CleverKeys-ML/ctc
O=/home/will/ctc-train/evalQ
EN192=artifacts/phaseM_kd_fresh_w1_s1234.onnx
EN80=$HOME/ctc-train/ckpt/phaseH-p50/ctc_swipe_encoder.onnx
RU_PROBE=$HOME/ctc-train/data/yandex_val10k.jsonl
SEED=${SEED:-1234}
sfx=""; tag=""
if [ "$SEED" != "1234" ]; then sfx="-s${SEED}"; tag="_s${SEED}"; fi
cd "$CTC" || exit 1
mkdir -p "$O"

for code in "$@"; do
  case "$code" in
    ru) layout=layouts/ru_jcuken_default.json ;;
    el) layout=layouts/el_qwerty.json ;;
    uk) layout=layouts/uk_jcuken.json ;;
    bg) layout=layouts/bg_bds.json ;;
    mk) layout=layouts/mk_lynyertdz.json ;;
    he) layout=layouts/he_1.json ;;
    *)  echo "unknown script $code" >&2; exit 2 ;;
  esac
  run="phaseQ-${code}-v3${sfx}"
  ck="ckpt/${run}/best.pt"
  fp32="ckpt/${run}/ctc_swipe_encoder.onnx"
  fp16="ckpt/${run}/ctc_swipe_encoder_fp16w.onnx"
  probe="$HOME/ctc-train/cache_${code}_v3/holdout.npz"
  echo "### [$code$sfx] export fp32"
  python3 export_onnx.py --layout "$CTC/$layout" --ckpt "$ck" --out "$fp32" \
      --parity-features "cache_${code}_v3/val.npz" \
      > "$O/${code}${tag}_export.log" 2>&1
  rc=$?
  tail -n 6 "$O/${code}${tag}_export.log"
  if [ $rc -ne 0 ]; then
    echo "### [$code$sfx] fp32 export FAILED at the default 1e-3 — retry at 2e-3"
    python3 export_onnx.py --layout "$CTC/$layout" --ckpt "$ck" --out "$fp32" \
      --parity-features "cache_${code}_v3/val.npz" --parity-tol 2e-3 \
      > "$O/${code}${tag}_export_tol2e-3.log" 2>&1
    tail -n 6 "$O/${code}${tag}_export_tol2e-3.log"
  fi
  ONNX="$HOME/ctc-train/$fp32"
  if [ -z "$tag" ]; then
    echo "### [$code] export fp16w"
    python3 quantize_onnx.py --layout "$CTC/$layout" --onnx "$fp32" --out "$fp16" \
        --mode fp16w --calib-npz "cache_${code}_v3/train_synth.npz" \
        2>&1 | tee "$O/${code}_fp16w.log" | tail -n 6
  fi
  echo "### [$code$sfx] holdout, CKDT preset"
  python3 eval_script.py --code "$code" --onnx "$ONNX" --probe "$probe" \
      --preset ckdt --progress 0 --dump "$O/dump_${code}_v3holdout${tag}.jsonl" \
      --out-json "$O/${code}_v3${tag}.json" > /dev/null 2>&1
  if [ "$code" = "ru" ]; then
    echo "### [ru$sfx] the REAL Yandex probe, eval-only footing"
    python3 eval_script.py --code ru --onnx "$ONNX" --probe "$RU_PROBE" \
        --preset ckdt --progress 0 --dump "$O/dump_ru_v3${tag}.jsonl" \
        --out-json "$O/ru_v3_ship${tag}.json" > /dev/null 2>&1
  fi
  if [ -z "$tag" ]; then
    echo "### [$code] holdout, fp16w"
    python3 eval_script.py --code "$code" --onnx "$HOME/ctc-train/$fp16" --probe "$probe" \
        --preset ckdt --progress 0 --out-json "$O/${code}_v3_fp16w.json" \
        > /dev/null 2>&1
    echo "### [$code] falsification control: permuted key centres"
    python3 eval_script.py --code "$code" --onnx "$ONNX" --probe "$probe" \
        --preset ckdt --progress 0 --permute-layout 4242 \
        --out-json "$O/${code}_permuted.json" > /dev/null 2>&1
    echo "### [$code] zero-shot controls on the same rows"
    python3 eval_script.py --code "$code" --onnx "$EN192" --probe "$probe" \
        --preset ckdt --progress 0 --out-json "$O/${code}_en192.json" > /dev/null 2>&1
    python3 eval_script.py --code "$code" --onnx "$EN80" --probe "$probe" \
        --preset ckdt --progress 0 --out-json "$O/${code}_en80.json" > /dev/null 2>&1
  fi
  python3 - "$code" "$tag" <<'PY'
import json, os, sys
o, c, tag = "/home/will/ctc-train/evalQ", sys.argv[1], sys.argv[2]
names = [f"v3{tag}"] + ([f"ship{tag}"] if c == "ru" else [])
if not tag:
    names += ["v3_fp16w", "permuted", "en192", "en80"]
for n in names:
    p = f"{o}/{c}_{n}.json" if not n.startswith("ship") else f"{o}/ru_v3_{n}.json"
    if not os.path.exists(p):
        continue
    d = json.load(open(p))
    print(f"  {n:12s} t1 {d['indict_t1']:6.2f}  t3 {d['indict_t3']:6.2f}  "
          f"t5 {d['indict_t5']:6.2f}  greedy {d['greedy_t1']:6.2f}  "
          f"<=3 {d['le3_t1']:6.2f}  4+ {d['ge4_t1']:6.2f}  n {d['decoded']}")
PY
done
echo PHASEQ-EVAL-DONE
